parameters.jsCode:
const trigger = $('Trigger Telegram').item.json;
const chatId = trigger.message.chat.id;
const text = (trigger.message.text || '').trim();

let companies = $('Buscar empresas del chat').item.json.companies;
if (typeof companies === 'string') { try { companies = JSON.parse(companies); } catch (e) { companies = []; } }
if (!Array.isArray(companies)) companies = [];

const conv = $('Obtener conversacion').item.json;
const conversationId = conv.id;
let state = conv.context_state_json;
if (typeof state === 'string') { try { state = JSON.parse(state); } catch (e) { state = {}; } }
if (!state || typeof state !== 'object') state = {};
let activeFlow = conv.active_flow;

const MENU = [
  '1) Marketing automatico',
  '2) Crear publicacion manual',
  '3) Revisar publicaciones',
  '4) Revisar clientes/leads',
  '5) Ver resultados',
  '6) Crear promocion',
  '7) Estado de proveedores de imagenes',
  '8) Otra cosa',
];

const TIPOS = ['promocion', 'producto', 'servicio', 'educativo', 'testimonial', 'marca', 'informativo', 'engagement', 'dejar_decidir'];
const TIPOS_LABEL = [
  '1) Promocion', '2) Producto', '3) Servicio', '4) Educativo', '5) Testimonial',
  '6) Marca', '7) Informativo', '8) Engagement', '9) Dejame decidir',
];

const FORMATO_DIMENSIONS = {
  cuadrado: { width: 1080, height: 1080, aspect_ratio: '1:1' },
  vertical: { width: 1080, height: 1350, aspect_ratio: '4:5' },
  story: { width: 1080, height: 1920, aspect_ratio: '9:16' },
};

function menuText(companyName) {
  return `Buenos dias.\n\nEstas trabajando con: ${companyName}.\n\nQue deseas hacer hoy?\n\n${MENU.join('\n')}\n\n(Responde con el numero o describelo con tus palabras. Escribe "cambiar empresa" para elegir otra.)`;
}
function askCompany(list) {
  return `Con cual empresa quieres trabajar?\n\n${list.map((c, i) => `${i + 1}) ${c.name}`).join('\n')}`;
}
function askCantidad() {
  return 'Cuantas publicaciones deseas hacer hoy? (maximo 5)';
}
function askRedes() {
  return 'Donde deseas publicar?\n\n1) Facebook\n2) Instagram\n3) WhatsApp\n4) Todas';
}
function askRedesManual() {
  return 'En cual red va esta publicacion?\n\n1) Facebook\n2) Instagram\n3) WhatsApp';
}
function askTipo() {
  return `Que tipo de contenido quieres?\n\n${TIPOS_LABEL.join('\n')}`;
}
function askIdioma() {
  return 'En que idioma quieres la publicacion?\n\n1) Espanol\n2) Ingles';
}
function askManualTema() {
  return 'Sobre que quieres que sea la publicacion? Describelo con tus palabras.\n\nPor ejemplo: "una promocion para el servicio de limpieza de oficinas" o "algo educativo sobre tecnicas de estudio para ninos".';
}
function askFormato() {
  return 'En que formato quieres la publicacion?\n\n1) Post cuadrado (1080x1080)\n2) Post vertical (1080x1350)\n3) Historia/Reel (1080x1920)';
}
function parseFormato(text) {
  const map = { '1': 'cuadrado', '2': 'vertical', '3': 'story' };
  const numMatch = text.match(/^(\d+)/);
  let formato = numMatch ? map[numMatch[1]] : null;
  if (!formato) {
    const lower = text.toLowerCase();
    if (lower.includes('cuadrad')) formato = 'cuadrado';
    else if (lower.includes('vertical')) formato = 'vertical';
    else if (lower.includes('story') || lower.includes('historia') || lower.includes('reel')) formato = 'story';
  }
  return formato;
}
function askModoImagen() {
  return 'Como quieres la imagen?\n\n1) Foto generada por IA\n2) Solo mis plantillas (sin foto, colores de marca)';
}
function parseModoImagen(text) {
  const numMatch = text.match(/^(\d+)/);
  if (numMatch) {
    if (numMatch[1] === '1') return 'ia';
    if (numMatch[1] === '2') return 'plantilla';
  }
  const lower = text.toLowerCase();
  if (lower.includes('plantilla')) return 'plantilla';
  if (lower.includes('foto') || lower.includes('ia')) return 'ia';
  return null;
}

function parseRedes(text, allowTodas) {
  const map = allowTodas
    ? { '1': 'facebook', '2': 'instagram', '3': 'whatsapp', '4': 'todas' }
    : { '1': 'facebook', '2': 'instagram', '3': 'whatsapp' };
  const numMatch = text.match(/^(\d+)/);
  let redes = numMatch ? map[numMatch[1]] : null;
  if (!redes) {
    const lower = text.toLowerCase();
    if (allowTodas && lower.includes('todas')) redes = 'todas';
    else if (lower.includes('facebook')) redes = 'facebook';
    else if (lower.includes('instagram')) redes = 'instagram';
    else if (lower.includes('whatsapp')) redes = 'whatsapp';
  }
  return redes;
}

function parseIdioma(text) {
  const numMatch = text.match(/^(\d+)/);
  let idioma = null;
  if (numMatch) {
    if (numMatch[1] === '1') idioma = 'es';
    else if (numMatch[1] === '2') idioma = 'en';
  }
  if (!idioma) {
    const lower = text.toLowerCase();
    if (lower.includes('espan') || lower.includes('spanish')) idioma = 'es';
    else if (lower.includes('ingl') || lower.includes('english')) idioma = 'en';
  }
  return idioma;
}

function brandContext(brain) {
  let services = brain.services;
  let promotions = brain.promotions;
  let rules = brain.rules;
  if (typeof services === 'string') { try { services = JSON.parse(services); } catch (e) { services = []; } }
  if (typeof promotions === 'string') { try { promotions = JSON.parse(promotions); } catch (e) { promotions = []; } }
  if (typeof rules === 'string') { try { rules = JSON.parse(rules); } catch (e) { rules = []; } }
  if (!Array.isArray(services)) services = [];
  if (!Array.isArray(promotions)) promotions = [];
  if (!Array.isArray(rules)) rules = [];
  return `Eres el redactor de marketing de la empresa "${brain.company_name}".
Sector: ${brain.sector || 'no especificado'}.
Descripcion: ${brain.description || 'no especificada'}.
Tono de comunicacion: ${brain.tone || 'profesional y cercano'}.
Colores de marca: ${brain.colors_primary || ''} y ${brain.colors_secondary || ''}.
Estilo visual: ${brain.visual_style || 'no especificado'}.

Servicios/productos reales disponibles (NUNCA inventes otros ni cambies precios):
${JSON.stringify(services)}

Promociones activas reales (si esta vacio, no hay promociones activas, no inventes ninguna):
${JSON.stringify(promotions)}

Reglas obligatorias:
${rules.join('\n')}`;
}

function hexToColorName(hex) {
  if (!hex) return 'colores neutros de la marca';
  const h = hex.replace('#', '');
  if (h.length !== 6) return 'los colores de la marca';
  const r = parseInt(h.slice(0, 2), 16) / 255;
  const g = parseInt(h.slice(2, 4), 16) / 255;
  const b = parseInt(h.slice(4, 6), 16) / 255;
  const max = Math.max(r, g, b), min = Math.min(r, g, b);
  const l = (max + min) / 2;
  if (max - min < 0.08) {
    if (l < 0.2) return 'negro';
    if (l > 0.85) return 'blanco';
    return 'gris';
  }
  let hue;
  if (max === r) hue = ((g - b) / (max - min)) % 6;
  else if (max === g) hue = (b - r) / (max - min) + 2;
  else hue = (r - g) / (max - min) + 4;
  hue = Math.round(hue * 60);
  if (hue < 0) hue += 360;
  if (l < 0.28 && hue >= 190 && hue <= 250) return 'azul marino';
  if (hue < 15 || hue >= 345) return 'rojo';
  if (hue < 45) return 'naranja';
  if (hue < 65) return 'amarillo';
  if (hue < 170) return 'verde';
  if (hue < 200) return 'celeste';
  if (hue < 250) return 'azul';
  if (hue < 290) return 'morado';
  if (hue < 345) return 'rosado';
  return 'un color de marca';
}

function jsonOutputSpec(idiomaNombre, cantidad, brain) {
  const colorName = hexToColorName(brain && brain.colors_primary);
  return `Responde SOLO con un arreglo JSON valido (sin texto adicional, sin markdown, sin bloque de codigo) de ${cantidad} objeto(s), cada uno con estas claves exactas: concept (string corto, en ${idiomaNombre}), headline (string CORTO Y CONTUNDENTE, maximo 8 palabras, en ${idiomaNombre}), caption (string, el texto completo del post para la red social, en ${idiomaNombre}), cta (string corto de 2 a 4 palabras, en ${idiomaNombre}), hashtags (arreglo de strings sin el simbolo #, en ${idiomaNombre} cuando aplique), alt_text (string describiendo la imagen para accesibilidad, en ${idiomaNombre}), bullets (arreglo de 2 a 4 strings MUY CORTOS, maximo 5 palabras cada uno, en ${idiomaNombre}, como etiquetas de beneficio -ej: 'Resultados impecables', 'Atencion 24/7'-, NUNCA oraciones completas, sin el simbolo de vinieta ni #), visual (objeto con SOLO estas 6 claves, cada valor un STRING SIMPLE en ingles -NUNCA un objeto ni un arreglo-: subject (maximo 12 palabras, quien o que es el sujeto principal, ligado al sector real de esta empresa: ${brain.sector || brain.description || 'this business'}), action (maximo 12 palabras, que esta haciendo, con un verbo terminado en -ing), setting (maximo 12 palabras, el lugar), props (maximo 12 palabras, 2 a 4 objetos fisicos separados por comas), wardrobe (maximo 8 palabras, SOLO el tipo de ropa, NUNCA menciones colores -el color de marca lo agrega el sistema-; usa string vacio '' si no hay personas en la escena), lighting (maximo 8 palabras, luz y ambiente). Ejemplo de OTRO sector, solo de referencia de formato, NO lo copies -este ejemplo es de una panaderia-: subject: \"two bakers\", action: \"shaping fresh bread dough on a counter\", setting: \"small bright artisan bakery kitchen\", props: \"flour, wooden rolling pin, bread baskets\", wardrobe: \"aprons and short-sleeve shirts\", lighting: \"warm morning light from a window\". Adapta CADA campo al sector REAL de esta empresa, nunca al ejemplo. Ningun campo debe mencionar texto, letreros, logos, marcas, nombres de empresas ni codigos de color), platform (una de: facebook, instagram, whatsapp).`;
}

function buildAutomaticoPrompt(brain, automatico) {
  const idiomaNombre = automatico.idioma === 'en' ? 'ingles (English)' : 'espanol';
  return `${brandContext(brain)}

Tarea: genera exactamente ${automatico.cantidad} publicaciones de tipo "${automatico.tipo}" para la(s) red(es) "${automatico.redes}".
IMPORTANTE: escribe TODO el contenido completamente en ${idiomaNombre}, sin mezclar idiomas.
${jsonOutputSpec(idiomaNombre, automatico.cantidad, brain)}
Si no hay suficiente informacion real de servicios o promociones para el tipo pedido, usa contenido informativo o de marca en su lugar, pero nunca inventes precios ni promociones que no esten en las listas de arriba.`;
}

function buildManualPrompt(brain, manual) {
  const idiomaNombre = manual.idioma === 'en' ? 'ingles (English)' : 'espanol';
  return `${brandContext(brain)}

El dueno de la empresa pidio especificamente esta publicacion, en sus propias palabras: "${manual.tema}"

Tarea: genera EXACTAMENTE 1 publicacion para la red "${manual.redes}" que cumpla con esa peticion, usando solo informacion real de las listas de arriba.
IMPORTANTE: escribe TODO el contenido completamente en ${idiomaNombre}, sin mezclar idiomas.
${jsonOutputSpec(idiomaNombre, 1, brain)}
Si la peticion menciona un precio, producto, servicio o promocion que NO aparece en las listas reales de arriba, NO lo inventes: escribe un enfoque informativo o de marca en su lugar y dejalo claro en el "concept".`;
}

function contentTypeLabel(t) {
  const map = {
    promocion: 'Promocion', producto: 'Producto', servicio: 'Servicio', educativo: 'Educativo',
    testimonial: 'Testimonial', marca: 'Marca', informativo: 'Informativo', engagement: 'Engagement',
    dejar_decidir: 'Contenido libre', manual: 'Publicacion manual',
  };
  return map[t] || t || 'Sin tipo';
}

function statusLabel(s) {
  const map = {
    DRAFT: 'Borrador', GENERATED: 'Generado (sin imagen todavia)', VALIDATED: 'Validado',
    PENDING_APPROVAL: 'Esperando tu aprobacion', APPROVED: 'Aprobado', SCHEDULED: 'Programado',
    PUBLISHING: 'Publicando', PUBLISHED: 'Publicado', FAILED: 'Fallo', CANCELLED: 'Cancelado',
  };
  return map[s] || s;
}

let reply;
let newState = state;
let newFlow = activeFlow;
let action = 'reply_only';
let geminiPrompt = null;
let automatico = null;
let manual = null;

if (companies.length === 0) {
  reply = `Hola. Tu chat de Telegram (chat_id: ${chatId}) todavia no esta vinculado a ninguna empresa. Pidele a Rafael que lo conecte.`;
} else if (/^cambiar\s+empresa/i.test(text)) {
  if (companies.length === 1) {
    newState = { company_id: companies[0].id };
    newFlow = null;
    reply = `Solo tienes una empresa conectada a este chat: ${companies[0].name}. Sigo trabajando con ella.\n\n${menuText(companies[0].name)}`;
  } else {
    newState = {};
    newFlow = 'select_company';
    reply = askCompany(companies);
  }
} else if (activeFlow === 'select_company' || (!state.company_id && companies.length > 1)) {
  let picked = null;
  const numMatch = text.match(/^(\d+)/);
  if (numMatch) {
    const idx = parseInt(numMatch[1], 10) - 1;
    if (companies[idx]) picked = companies[idx];
  }
  if (!picked) {
    const lower = text.toLowerCase();
    picked = companies.find((c) => lower.includes(c.name.toLowerCase()) || c.name.toLowerCase().includes(lower));
  }
  if (picked) {
    newState = { company_id: picked.id };
    newFlow = null;
    reply = menuText(picked.name);
  } else {
    newFlow = 'select_company';
    reply = `No reconoci esa opcion. ${askCompany(companies)}`;
  }
} else if (!state.company_id && companies.length === 1) {
  newState = { company_id: companies[0].id };
  newFlow = null;
  reply = menuText(companies[0].name);
} else {
  const company = companies.find((c) => c.id === state.company_id) || companies[0];

  if (activeFlow === 'auto_cantidad') {
    const n = parseInt(text, 10);
    if (!isNaN(n) && n >= 1 && n <= 5) {
      newState = { ...state, automatico: { cantidad: n } };
      newFlow = 'auto_redes';
      reply = askRedes();
    } else {
      newFlow = 'auto_cantidad';
      reply = `Escribe un numero entre 1 y 5. ${askCantidad()}`;
    }
  } else if (activeFlow === 'auto_redes') {
    const redes = parseRedes(text, true);
    if (redes) {
      const prevAuto = state.automatico || {};
      newState = { ...state, automatico: { ...prevAuto, redes } };
      newFlow = 'auto_formato';
      reply = askFormato();
    } else {
      newFlow = 'auto_redes';
      reply = `No reconoci esa red. ${askRedes()}`;
    }
  } else if (activeFlow === 'auto_formato') {
    const formato = parseFormato(text);
    if (formato) {
      const prevAuto = state.automatico || {};
      newState = { ...state, automatico: { ...prevAuto, formato } };
      newFlow = 'auto_modo_imagen';
      reply = askModoImagen();
    } else {
      newFlow = 'auto_formato';
      reply = `No reconoci ese formato. ${askFormato()}`;
    }
  } else if (activeFlow === 'auto_modo_imagen') {
    const modoImagen = parseModoImagen(text);
    if (modoImagen) {
      const prevAuto = state.automatico || {};
      newState = { ...state, automatico: { ...prevAuto, modo_imagen: modoImagen } };
      newFlow = 'auto_tipo';
      reply = askTipo();
    } else {
      newFlow = 'auto_modo_imagen';
      reply = `No reconoci esa opcion. ${askModoImagen()}`;
    }
  } else if (activeFlow === 'auto_tipo') {
    const numMatch = text.match(/^(\d+)/);
    let tipo = null;
    if (numMatch) {
      const idx = parseInt(numMatch[1], 10) - 1;
      tipo = TIPOS[idx];
    }
    if (!tipo) {
      const lower = text.toLowerCase();
      if (lower.includes('decidir')) tipo = 'dejar_decidir';
      else tipo = TIPOS.find((t) => lower.includes(t));
    }
    if (tipo) {
      const prevAuto = state.automatico || {};
      newState = { ...state, automatico: { ...prevAuto, tipo } };
      newFlow = 'auto_idioma';
      reply = askIdioma();
    } else {
      newFlow = 'auto_tipo';
      reply = `No reconoci esa opcion. ${askTipo()}`;
    }
  } else if (activeFlow === 'auto_idioma') {
    const idioma = parseIdioma(text);
    if (idioma) {
      const prevAuto = state.automatico || {};
      automatico = { ...prevAuto, idioma };
      newState = { ...state, automatico };
      newFlow = null;
      action = 'generate_content';
      reply = `Generando ${automatico.cantidad} publicaciones para ${company.name} en ${idioma === 'en' ? 'ingles' : 'espanol'}, dame un momento...`;

      const brain = $('Cargar Company Brain').item.json;
      geminiPrompt = buildAutomaticoPrompt(brain, automatico);
    } else {
      newFlow = 'auto_idioma';
      reply = `No reconoci esa opcion. ${askIdioma()}`;
    }
  } else if (activeFlow === 'manual_tema') {
    if (text.length < 3) {
      newFlow = 'manual_tema';
      reply = `Cuentame un poco mas. ${askManualTema()}`;
    } else {
      newState = { ...state, manual: { tema: text } };
      newFlow = 'manual_redes';
      reply = askRedesManual();
    }
  } else if (activeFlow === 'manual_redes') {
    const redes = parseRedes(text, false);
    if (redes) {
      const prevManual = state.manual || {};
      newState = { ...state, manual: { ...prevManual, redes } };
      newFlow = 'manual_formato';
      reply = askFormato();
    } else {
      newFlow = 'manual_redes';
      reply = `No reconoci esa red. ${askRedesManual()}`;
    }
  } else if (activeFlow === 'manual_formato') {
    const formato = parseFormato(text);
    if (formato) {
      const prevManual = state.manual || {};
      newState = { ...state, manual: { ...prevManual, formato } };
      newFlow = 'manual_modo_imagen';
      reply = askModoImagen();
    } else {
      newFlow = 'manual_formato';
      reply = `No reconoci ese formato. ${askFormato()}`;
    }
  } else if (activeFlow === 'manual_modo_imagen') {
    const modoImagen = parseModoImagen(text);
    if (modoImagen) {
      const prevManual = state.manual || {};
      newState = { ...state, manual: { ...prevManual, modo_imagen: modoImagen } };
      newFlow = 'manual_idioma';
      reply = askIdioma();
    } else {
      newFlow = 'manual_modo_imagen';
      reply = `No reconoci esa opcion. ${askModoImagen()}`;
    }
  } else if (activeFlow === 'manual_idioma') {
    const idioma = parseIdioma(text);
    if (idioma) {
      const prevManual = state.manual || {};
      manual = { ...prevManual, idioma };
      newState = { ...state, manual };
      newFlow = null;
      action = 'generate_content';
      reply = `Generando tu publicacion sobre "${manual.tema}" para ${company.name} en ${idioma === 'en' ? 'ingles' : 'espanol'}, dame un momento...`;

      const brain = $('Cargar Company Brain').item.json;
      geminiPrompt = buildManualPrompt(brain, manual);
    } else {
      newFlow = 'manual_idioma';
      reply = `No reconoci esa opcion. ${askIdioma()}`;
    }
  } else if (/^1\b/.test(text) || /automatico/i.test(text)) {
    newFlow = 'auto_cantidad';
    reply = askCantidad();
  } else if (/^2\b/.test(text) || /publicaci.n\s+manual/i.test(text)) {
    newState = { ...state, manual: {} };
    newFlow = 'manual_tema';
    reply = askManualTema();
  } else if (/^7\b/.test(text) || /estado.*proveedor/i.test(text) || /(higgsfield|gemini)/i.test(text)) {
    action = 'check_providers';
    reply = 'Verificando el estado de Gemini (imagenes), un momento...';
  } else if (/^3\b/.test(text) || /revisar\s+public/i.test(text)) {
    let items = $('Buscar publicaciones recientes').item.json.recent_items;
    if (typeof items === 'string') { try { items = JSON.parse(items); } catch (e) { items = []; } }
    if (!Array.isArray(items)) items = [];

    if (items.length === 0) {
      reply = `Todavia no hay publicaciones generadas para ${company.name}.\n\n${menuText(company.name)}`;
    } else {
      const lines = items.map((it) => `#${it.id} [${statusLabel(it.status)}] ${contentTypeLabel(it.content_type)} en ${it.platform || 'sin red'} (${it.created_at})\n"${it.headline}"`);
      reply = `Ultimas ${items.length} publicacion(es) de ${company.name}:\n\n${lines.join('\n\n')}\n\n${menuText(company.name)}`;
    }
  } else {
    reply = `Elegiste: "${text}" para ${company.name}.\n\n(Esta opcion del menu se construye en un proximo incremento de la Fase 4.)\n\n${menuText(company.name)}`;
  }
}

return [{
  json: {
    chat_id: chatId,
    reply_text: reply,
    conversation_id: conversationId,
    new_state: JSON.stringify(newState),
    new_flow: newFlow,
    action,
    company_id: (newState && newState.company_id) || null,
    content_type: automatico ? automatico.tipo : (manual ? 'manual' : null),
    formato: (automatico && automatico.formato) || (manual && manual.formato) || 'cuadrado',
    modo_imagen: (automatico && automatico.modo_imagen) || (manual && manual.modo_imagen) || 'ia',
    brand_color_name: (typeof hexToColorName === 'function') ? hexToColorName((($('Cargar Company Brain').item.json) || {}).colors_primary) : '',
    gemini_prompt: geminiPrompt,
    idioma: (automatico && automatico.idioma) || (manual && manual.idioma) || null,
    tema: (manual && manual.tema) || '',
    modo: automatico ? 'automatic' : (manual ? 'manual' : null),
  },
}];

const decision = $('Decidir respuesta').item.json;
let state = {};
try { state = JSON.parse(decision.new_state); } catch (e) { state = {}; }
const cleanState = { company_id: state.company_id || decision.company_id || null };

return [{
  json: {
    chat_id: decision.chat_id,
    reply_text: 'Hubo un problema generando el contenido: el proveedor de IA esta ocupado en este momento (error temporal). Intenta de nuevo en un minuto escribiendo "1".',
    conversation_id: decision.conversation_id,
    new_state: JSON.stringify(cleanState),
    new_flow: null,
  },
}];

const decision = $('Decidir respuesta').item.json;
const geminiResponse = $input.first().json;

let draftsRaw = [];
let usage = {};
let parseError = null;
try {
  const text = geminiResponse.candidates[0].content.parts[0].text;
  draftsRaw = JSON.parse(text);
  if (!Array.isArray(draftsRaw)) draftsRaw = [draftsRaw];
} catch (e) {
  parseError = String(e);
  draftsRaw = [];
}
usage = geminiResponse.usageMetadata || {};

const drafts = draftsRaw.map((d) => ({
  concept: d.concept || '',
  headline: d.headline || '',
  caption: d.caption || '',
  cta: d.cta || '',
  hashtags: Array.isArray(d.hashtags) ? d.hashtags : [],
  alt_text: d.alt_text || '',
  bullets: Array.isArray(d.bullets) ? d.bullets : [],
  visual: d.visual,
  image_prompt: (typeof d.image_prompt === 'string' ? d.image_prompt : ''),
  platform: d.platform || (decision.content_type || null),
}));

let replyText;
if (drafts.length === 0) {
  replyText = `Hubo un problema generando el contenido con la IA (${parseError || 'respuesta vacia'}). Intenta de nuevo escribiendo "1".`;
} else {
  const lines = drafts.map((d, i) => {
    const hashtagsText = d.hashtags.map((h) => '#' + h).join(' ');
    return `--- Publicacion ${i + 1} (${d.platform}) ---\n${d.headline}\n\n${d.caption}\n\nCTA: ${d.cta}\nHashtags: ${hashtagsText}`;
  });
  replyText = `Aqui tienes ${drafts.length} publicacion(es) generadas para revisar:\n\n${lines.join('\n\n')}\n\n(La aprobacion y edicion desde Telegram se conecta en el siguiente incremento; por ahora quedan guardadas como borradores en el sistema.)`;
}

const inputTokens = usage.promptTokenCount || 0;
const outputTokens = usage.candidatesTokenCount || 0;
// Precio promocional gemini-3.6-flash (docs/research/08_ai_text_providers_and_safety.md): $0.75 / $3.75 por millon de tokens
const estimatedCost = (inputTokens / 1000000) * 0.75 + (outputTokens / 1000000) * 3.75;

return [{
  json: {
    chat_id: decision.chat_id,
    reply_text: replyText,
    conversation_id: decision.conversation_id,
    new_state: decision.new_state,
    new_flow: decision.new_flow,
    company_id: decision.company_id,
    content_type: decision.content_type,
    formato: decision.formato,
    modo_imagen: decision.modo_imagen,
    drafts_json: JSON.stringify(drafts),
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    estimated_cost: estimatedCost,
    model_used: 'gemini-3.6-flash',
  },
}];

// Nodo Code "Preparar imagen" (01_CHANNEL_Telegram).
// Tres entradas posibles:
//   a) resultado de "Procesar respuesta Gemini" (gemini_result=true)  -> imagen generada o fallo con costo
//   b) "Reclamar job" con claimed=false                               -> solicitud duplicada, no se genera
//   c) "Cost Guard" (image_allowed=false)                             -> simulacion/bloqueo, sin imagen
// Salida: campos que usan "Guardar imagen en BD", "Registrar costo imagen" y "Construir HTML de plantilla".

const decision = $('Guardar borradores').item.json;
const input = $input.first().json || {};

let drafts = [];
try { drafts = JSON.parse(decision.drafts_json); } catch (e) { drafts = []; }
const first = drafts[0] || {};

function cop(n) { return 'COP ' + String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.'); }

let replyText = decision.reply_text;
let imageStoragePath = null;
let photoDataUri = null;
let jobStatus = null;
let costUsd = 0;
let costCop = 0;
let errorDetail = null;
let jobId = null;
let model = null;

if (input.gemini_result) {
  jobId = input.job_id;
  model = input.model;
  costUsd = Number(input.cost_usd) || 0;
  costCop = Number(input.cost_cop) || 0;
  if (input.ok) {
    photoDataUri = input.photo_data_uri;
    imageStoragePath = 'storage/generated/' + decision.company_id + '/' + decision.first_item_id + '_bg.' + (input.image_ext || 'png');
    jobStatus = 'DONE';
    replyText += '\n\n--- Imagen con IA ---\nModelo: ' + input.model + ' (' + input.image_size + ') | Costo ' + (input.cost_source === 'usageMetadata' ? 'real' : 'estimado') + ': ' + cop(costCop) + ' (USD ' + costUsd.toFixed(4) + ')';
  } else {
    jobStatus = 'FAILED';
    errorDetail = input.error_detail;
    replyText += '\n\nNo se pudo generar la imagen con IA: ' + input.error_detail + '. ' + (input.billed ? 'Se registro ' + cop(costCop) + ' porque Google pudo cobrarlo.' : 'No se cobro nada.') + ' No se reintento automaticamente.';
  }
} else if (input.claimed === false) {
  replyText += '\n\nEsta solicitud ya se estaba procesando (proteccion anti-duplicados): no se genero otra imagen.';
} else if (decision.modo_imagen !== 'plantilla') {
  let guardText = '';
  try { guardText = $('Cost Guard').item.json.dry_run_text || ''; } catch (e) { guardText = ''; }
  replyText += '\n\n' + (guardText || '(No se genero foto con IA. El texto ya quedo listo.)');
}

return [{
  json: {
    chat_id: decision.chat_id,
    reply_text: replyText,
    conversation_id: decision.conversation_id,
    new_state: decision.new_state,
    new_flow: decision.new_flow,
    content_item_id: decision.first_item_id,
    image_url: imageStoragePath,
    photo_data_uri: photoDataUri,
    image_caption: (first.headline || '').slice(0, 900),
    job_id: jobId,
    job_status: jobStatus,
    cost_usd: costUsd,
    cost_cop: costCop,
    error_detail: errorDetail,
    model,
  },
}];

const decision = $('Guardar borradores').item.json;
return [{
  json: {
    chat_id: decision.chat_id,
    reply_text: decision.reply_text + '\n\n(La imagen esta tardando mas de lo esperado; el texto ya quedo listo. Puedes revisar la imagen mas tarde en \'Revisar publicaciones\'.)',
    conversation_id: decision.conversation_id,
    new_state: decision.new_state,
    new_flow: decision.new_flow,
  },
}];

