  action: 'shaping fresh bread dough on a counter',
  setting: 'small bright artisan bakery kitchen',
  props: 'flour, wooden rolling pin, bread baskets',
  wardrobe: 'aprons and short-sleeve shirts',
  lighting: 'warm morning light from a window',
};

const FIELD_LIMITS = { subject: 12, action: 12, setting: 12, props: 12, wardrobe: 8, lighting: 8 };

const FORBIDDEN_RE = /\b(text|logo|logos|sign|signage|lettering|slogan|caption|brand|branded|trademark|watermark|words)\b/i;
const HEX_RE = /#[0-9a-fA-F]{3,6}\b/;
const COLOR_WORDS_RE = /\b(red|orange|yellow|green|blue|navy|purple|pink|black|white|gray|grey|brown|gold|golden|teal|cyan|magenta)\b/i;
const SPANISH_HINT_RE = /[\u00e1\u00e9\u00ed\u00f3\u00fa\u00f1\u00bf\u00a1]| de | la | el | con | para /i;

function looksSpanish(s) {
  return SPANISH_HINT_RE.test(' ' + s + ' ');
}

// Frases de marketing ("Our Expertise...", "Transform Your...") NO son escenas: producen texto dibujado en la imagen.
const SLOGAN_RE = /\b(our|your|we|us|transform|expertise|services?|solutions?|quality|best|everywhere)\b/i;
function titleCaseCount(s) { return s.split(' ').filter((w) => /^[A-Z][a-z]+$/.test(w)).length; }

function cleanField(raw, key) {
  let v = raw;
  if (v == null) return '';
  if (typeof v === 'object') {
    if (Array.isArray(v)) v = v.join(', ');
    else if (typeof v.description === 'string') v = v.description;
    else {
      const strVals = Object.values(v).filter((x) => typeof x === 'string');
      v = strVals.join(', ');
    }
  }
  v = String(v);
  v = v.replace(/["'\n\r]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!v) return '';
  if (!/[a-zA-Z]/.test(v)) return '';
  if (v.toLowerCase() === String(EXAMPLE_VALUES[key] || '').toLowerCase()) return '';
  if (looksSpanish(v)) return '';
  if (FORBIDDEN_RE.test(v)) return '';
  if (SLOGAN_RE.test(v)) return '';
  if (titleCaseCount(v) >= 3) return '';
  if (HEX_RE.test(v)) return '';
  if (key === 'wardrobe' && COLOR_WORDS_RE.test(v)) return '';
  const words = v.split(' ');
  const limit = FIELD_LIMITS[key] || 12;
  if (words.length > limit) v = words.slice(0, limit).join(' ');
  return v;
}

function sectorFallback(sector, description) {
